node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search across multiple tables for A58410
const tables = ['hotel_reservations','flight_bookings','car_rentals','orders'];
for (const t of tables) {
  const rows = db.prepare('SELECT * FROM ' + t).all();
  for (const r of rows) {
    const vals = Object.values(r).map(String);
    if (vals.some(v => v.includes('A58410'))) {
      console.log('Found in', t, ':', JSON.stringify(r, null, 2));
    }
  }
}
// Also try a direct LIKE search
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t + ')').all();
  for (const c of cols) {
    try {
      const rows = db.prepare('SELECT * FROM ' + t + ' WHERE CAST(' + c.name + ' AS TEXT) LIKE ?').all('%A58410%');
      if (rows.length > 0) {
        console.log('Match in', t + '.' + c.name, ':', JSON.stringify(rows, null, 2));
      }
    } catch(e) {}
  }
}
"

